-- =====================================================================
-- Session 496 migration — canon / Luke 1–24 — Phase 2 REBUILD, batch l1: the orphan cards rewritten Come-and-See and threaded.
-- 61 cards rewritten in place (ids and verse pairs kept), 1 new thread(s), 1 unanchored thread(s) anchored, 61 thread members added.
-- Drafted on: Claude Sonnet 5.5 (claude-sonnet-5-5), claude-sonnet-5-5; read and corrected on Claude Fable 5.1; every note composed by script (assemble496.py): target verse whole
-- from parsed/canon.json (restored-names KJV, the canon convention), Luke verse whole from the live text of the read-back, then the prose.
-- Safety (DO block, before any write): RAISES if a card id is gone or sits on another verse pair, if a Luke verse's live text differs from the
-- read-back, if a card's live note is neither the note this was written against nor the new one, if a card is already in a thread this file does
-- not put it in, if a thread to join / an anchor verse is missing, or if a thread to anchor already has a different anchor.
-- Idempotent: a re-run reports 0 rewritten / 0 inserted / 0 anchored.  Nothing is deleted.
-- Run: python3 api/apply_migration.py data-schema/migrations/session496_luke_l1_rebuild.sql
-- =====================================================================
\echo 'session496 — Luke 1–24 rebuild starting...'
BEGIN;
CREATE TEMP TABLE _s496_l1_c (id BIGINT, src_ch INT, src_v INT, src_text TEXT, tgt_slug TEXT, tgt_ch INT, tgt_v INT, old_note TEXT, new_note TEXT) ON COMMIT DROP;
CREATE TEMP TABLE _s496_l1_t (slug TEXT, title TEXT, summary_md TEXT, ch INT, a_vn INT, z_vn INT, tier TEXT, sort_order INT) ON COMMIT DROP;

*And, behold, thou shalt conceive in thy womb, and bring forth a son, and shalt call his name Yahusha (JESUS).* (Luke 1:31)

Yahuah (the LORD) had told David what would come after him:

*And when thy days be fulfilled, and thou shalt sleep with thy fathers, I will set up thy seed after thee, which shall proceed out of thy bowels, and I will establish his kingdom.* (2 Samuel 7:12)

*He shall build an house for my name, and I will stablish the throne of his kingdom for ever.* (2 Samuel 7:13)

Gabriel says the same thing and names the throne:

*He shall be great, and shall be called the Son of the Highest: and Yahuah Elohim (the Lord God) shall give unto him the throne of his father David:* (Luke 1:32)

It is one seed and one throne, David's, and the son it is given to is Mary's. Then comes the length of it:

*And he shall reign over the house of Jacob for ever; and of his kingdom there shall be no end.* (Luke 1:33)

Daniel was shown the same kingdom given, in a vision of his own:

*And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* (Daniel 7:14)

Nothing is turned into something else here. The throne is David's throne, the reign is over the house of Jacob, which is all twelve tribes and not another people standing in their place, and the kingdom does not pass away. Gabriel is keeping the word given to David, one promise standing from David to Mary.$n$,1,31,33,'free',3406);
CREATE TEMP TABLE _s496_l1_a (slug TEXT, book TEXT, ch INT, a_vn INT, z_vn INT) ON COMMIT DROP;
CREATE TEMP TABLE _s496_l1_m (thread_slug TEXT, card_id BIGINT, ord INT, member_note TEXT) ON COMMIT DROP;

CREATE OR REPLACE TEMP VIEW _s496_l1_lookup AS
SELECT b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id, v.text
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug = 'canon';

DO $s496$
DECLARE r RECORD; sid BIGINT; tid BIGINT; ltext TEXT; cur RECORD; n INT; av BIGINT; zv BIGINT;
        n_note INT := 0; n_note_same INT := 0; n_thr INT := 0; n_thr_same INT := 0; n_anc INT := 0; n_anc_same INT := 0; n_mem INT := 0; n_mem_same INT := 0; n_total INT;
BEGIN
  -- ---- guards: every row is checked before anything is written ----
  FOR r IN SELECT * FROM _s496_l1_c LOOP
    SELECT verse_id, text INTO sid, ltext FROM _s496_l1_lookup WHERE book_slug = 'luke' AND chapter_number = r.src_ch AND verse_number = r.src_v;
    IF sid IS NULL THEN RAISE EXCEPTION 'S496: source verse luke %:% missing', r.src_ch, r.src_v; END IF;
    IF ltext <> r.src_text THEN RAISE EXCEPTION 'S496: live text of luke %:% differs from the read-back this migration was written against — re-run the dump and rebuild', r.src_ch, r.src_v; END IF;
    SELECT verse_id INTO tid FROM _s496_l1_lookup WHERE book_slug = r.tgt_slug AND chapter_number = r.tgt_ch AND verse_number = r.tgt_v;
    IF tid IS NULL THEN RAISE EXCEPTION 'S496: target verse % %:% missing', r.tgt_slug, r.tgt_ch, r.tgt_v; END IF;
    SELECT * INTO cur FROM cross_references WHERE id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S496: card % is gone', r.id; END IF;
    IF cur.source_verse_id <> sid OR cur.target_verse_id <> tid THEN RAISE EXCEPTION 'S496: card % no longer sits on luke %:% -> % %:%', r.id, r.src_ch, r.src_v, r.tgt_slug, r.tgt_ch, r.tgt_v; END IF;
    IF cur.note IS DISTINCT FROM r.old_note AND cur.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S496: the live note of card % differs from the read-back this migration was written against — re-run the dump and rebuild', r.id; END IF;
    IF EXISTS (SELECT 1 FROM cross_reference_thread_members mm JOIN cross_reference_threads th ON th.id = mm.thread_id
                WHERE mm.cross_reference_id = r.id AND NOT EXISTS (SELECT 1 FROM _s496_l1_m m WHERE m.card_id = r.id AND m.thread_slug = th.slug)) THEN
      RAISE EXCEPTION 'S496: card % already sits in a thread this migration does not put it in — re-run the dump and rebuild', r.id; END IF;
  END LOOP;
  FOR r IN SELECT * FROM _s496_l1_t LOOP
    IF NOT EXISTS (SELECT 1 FROM _s496_l1_lookup WHERE book_slug = 'luke' AND chapter_number = r.ch AND verse_number = r.a_vn)
    OR NOT EXISTS (SELECT 1 FROM _s496_l1_lookup WHERE book_slug = 'luke' AND chapter_number = r.ch AND verse_number = r.z_vn) THEN
      RAISE EXCEPTION 'S496: anchor %:%-% for new thread % missing', r.ch, r.a_vn, r.z_vn, r.slug; END IF;
  END LOOP;
  FOR r IN SELECT * FROM _s496_l1_a LOOP
    SELECT verse_id INTO av FROM _s496_l1_lookup WHERE book_slug = r.book AND chapter_number = r.ch AND verse_number = r.a_vn;
    SELECT verse_id INTO zv FROM _s496_l1_lookup WHERE book_slug = r.book AND chapter_number = r.ch AND verse_number = r.z_vn;
    IF av IS NULL OR zv IS NULL THEN RAISE EXCEPTION 'S496: anchor verse % %:%-% for thread % missing', r.book, r.ch, r.a_vn, r.z_vn, r.slug; END IF;
    SELECT * INTO cur FROM cross_reference_threads WHERE slug = r.slug;
    IF NOT FOUND THEN RAISE EXCEPTION 'S496: thread to anchor % does not exist', r.slug; END IF;
    IF cur.anchor_verse_id_start IS NOT NULL AND (cur.anchor_verse_id_start <> av OR cur.anchor_verse_id_end IS DISTINCT FROM zv) THEN
      RAISE EXCEPTION 'S496: thread % already carries a different anchor — re-run the dump and rebuild', r.slug; END IF;
  END LOOP;
  FOR r IN SELECT DISTINCT thread_slug FROM _s496_l1_m LOOP
    IF NOT EXISTS (SELECT 1 FROM cross_reference_threads WHERE slug = r.thread_slug) AND NOT EXISTS (SELECT 1 FROM _s496_l1_t WHERE slug = r.thread_slug) THEN
      RAISE EXCEPTION 'S496: thread to join % does not exist', r.thread_slug; END IF;
  END LOOP;

  -- ---- notes rewritten in place ----
  SELECT count(*) INTO n_total FROM _s496_l1_c;
  UPDATE cross_references x SET note = c.new_note FROM _s496_l1_c c WHERE x.id = c.id AND x.note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_note = ROW_COUNT; n_note_same := n_total - n_note;

  -- ---- new threads ----
  SELECT count(*) INTO n_total FROM _s496_l1_t;
  SELECT t.slug, t.title, t.summary_md, sv.verse_id, ev.verse_id, t.tier::content_tier, t.sort_order
    FROM _s496_l1_t t
    JOIN _s496_l1_lookup sv ON sv.book_slug='luke' AND sv.chapter_number=t.ch AND sv.verse_number=t.a_vn
    JOIN _s496_l1_lookup ev ON ev.book_slug='luke' AND ev.chapter_number=t.ch AND ev.verse_number=t.z_vn
  ON CONFLICT (slug) DO NOTHING;
  GET DIAGNOSTICS n_thr = ROW_COUNT; n_thr_same := n_total - n_thr;

  -- ---- anchors for the unanchored threads these cards join ----
  SELECT count(*) INTO n_total FROM _s496_l1_a;
  UPDATE cross_reference_threads th SET anchor_verse_id_start = sv.verse_id, anchor_verse_id_end = ev.verse_id
    FROM _s496_l1_a a
    JOIN _s496_l1_lookup sv ON sv.book_slug=a.book AND sv.chapter_number=a.ch AND sv.verse_number=a.a_vn
    JOIN _s496_l1_lookup ev ON ev.book_slug=a.book AND ev.chapter_number=a.ch AND ev.verse_number=a.z_vn
   WHERE th.slug = a.slug AND th.anchor_verse_id_start IS NULL;
  GET DIAGNOSTICS n_anc = ROW_COUNT; n_anc_same := n_total - n_anc;

  -- ---- members: each card into its thread, after the thread's live maximum, in source verse order ----
  SELECT count(*) INTO n_total FROM _s496_l1_m;
  SELECT th.id, m.card_id,
         COALESCE((SELECT max(mm.sort_order) FROM cross_reference_thread_members mm WHERE mm.thread_id = th.id), 0)
           + row_number() OVER (PARTITION BY th.id ORDER BY m.ord, m.card_id),
         m.member_note
    FROM _s496_l1_m m JOIN cross_reference_threads th ON th.slug = m.thread_slug
   WHERE NOT EXISTS (SELECT 1 FROM cross_reference_thread_members mm WHERE mm.thread_id = th.id AND mm.cross_reference_id = m.card_id)
  ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
  GET DIAGNOSTICS n_mem = ROW_COUNT; n_mem_same := n_total - n_mem;

  -- ---- proof before commit: every card carries its new note and sits in its thread ----
  SELECT count(*) INTO n FROM _s496_l1_c c JOIN cross_references x ON x.id = c.id WHERE x.note IS DISTINCT FROM c.new_note;
  IF n > 0 THEN RAISE EXCEPTION 'S496: % card(s) do not carry the new note', n; END IF;
  SELECT count(*) INTO n FROM _s496_l1_m m WHERE NOT EXISTS (
    SELECT 1 FROM cross_reference_thread_members mm JOIN cross_reference_threads th ON th.id = mm.thread_id AND th.slug = m.thread_slug WHERE mm.cross_reference_id = m.card_id);
  IF n > 0 THEN RAISE EXCEPTION 'S496: % member row(s) did not land', n; END IF;
  SELECT count(*) INTO n FROM _s496_l1_a a JOIN cross_reference_threads th ON th.slug = a.slug WHERE th.anchor_verse_id_start IS NULL;
  IF n > 0 THEN RAISE EXCEPTION 'S496: % thread(s) still unanchored', n; END IF;

  RAISE NOTICE 'S496 (luke l1) summary: notes rewritten % / already there %; threads inserted % / already there %; anchors set % / already there %; members inserted % / already there %',
    n_note, n_note_same, n_thr, n_thr_same, n_anc, n_anc_same, n_mem, n_mem_same;
END $s496$;
COMMIT;
\echo 'session496 — Luke 1–24 rebuild done.'
